import type { LookupValue } from "@conch/core";

import { classifyLookupValue, MAX_LOOKUP_INPUT } from "@conch/core";

export interface ClipboardSource {
  enabled(): boolean;
  formats(): string[] | null;
  readText(): string | null;
}

// nspasteboard.org markers that password managers and clipboard tools set on
// items that must not be read or kept.
export const PRIVATE_PASTEBOARD_TYPES: ReadonlySet<string> = new Set([
  "org.nspasteboard.ConcealedType",
  "org.nspasteboard.TransientType",
  "org.nspasteboard.AutoGeneratedType",
]);

// Without the pasteboard's real types a concealed password can't be told
// apart from an id, so an unknown answer means "don't read".
const isReadable = (formats: string[] | null): boolean =>
  formats !== null &&
  !formats.some((format) => PRIVATE_PASTEBOARD_TYPES.has(format));

export const createClipboardOffer =
  (source: ClipboardSource) => (): LookupValue | null => {
    if (!(source.enabled() && isReadable(source.formats()))) {
      return null;
    }
    const text = source.readText();
    return text === null
      ? null
      : classifyLookupValue(text.slice(0, MAX_LOOKUP_INPUT));
  };
